                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('sustain_warning'), 'warning'
                );
                return false;
            }

            if (decisions.expandMarket !== 'none') {
                var ds = window.mySimulation.state.domainState;
                var market = this._findMarket(decisions.expandMarket);
                if (market && ds.cash < market.entryFee) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('cash_warning'), 'warning'
                    );
                    return false;
                }
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var self = this;
            var period = state.currentPeriod;
            var T = function(k) { return window.mySimulation.t(k); };
            var pct = Math.max(0, Math.min(15, Number(d.sustainabilityPct) || 0));
            if (!ds.entryQuarter) ds.entryQuarter = {};
            if (!ds.entryFit) ds.entryFit = {};

            // 1. Revenue by market, from the markets active when the quarter opens (a market entered this quarter sells from next quarter)
            var startMarkets = ds.activeMarkets.slice();
            // the ESG record buyers see this quarter: the rating after the investment and production choice of this quarter
            var esgSeen = Math.max(0, Math.min(100, ds.esgRating + this._esgStep(d, pct, ds.esgRating)));
            var credible = Math.max(0, Math.min(1, (esgSeen - 45) / 15));
            var marketRevenues = {};
            var totalRevenue = 0;
            var marginRate = 0.32;
            if (d.pricingStrategy === 'mass') marginRate = 0.25;
            if (d.pricingStrategy === 'premium') marginRate = 0.42;
            startMarkets.forEach(function(mId) {
                var m = self._findMarket(mId);
                if (!m) return;
                var share = ds.marketShares[mId] || 0;
                var fit = self._esgFit(m, ds.esgRating, period);
                var vol = 1.0;
                if (d.pricingStrategy === 'mass') vol = 1.12;
                // ESG as a demand signal: a premium price holds its volume only where buyers reward a credible ESG record
                if (d.pricingStrategy === 'premium') vol = 0.76 + 0.26 * fit;
                var rev = (m.size / 4) * (share / 100) * (1 + m.growth / 4) * vol;
                marketRevenues[mId] = rev;
                totalRevenue += rev;
                // share movement: pricing, ESG fit and the ramp of a recently entered market
                var dShare = 0.15;
                if (d.pricingStrategy === 'mass') dShare = 0.35;
                // a premium price ahead of a credible ESG record reads as a plain price rise: rivals take share until the record catches up
                if (d.pricingStrategy === 'premium') dShare = -self.PREMIUM_DRIFT * (1 - credible);
                dShare += (m.home ? 0.25 : 0.45) * fit;
                // where buyers score suppliers on ESG, a weak record loses share every quarter
                if (m.esgPressure >= 0.7 && ds.esgRating < 60 && (!m.home || period >= 5)) dShare -= 0.5;
                var since = ds.entryQuarter[mId];
                if (since && period - since <= 4) dShare += 0.3 + 1.2 * (ds.entryFit[mId] || 0);
                ds.marketShares[mId] = Math.max(1, Math.min(share + dShare, 35));
            });

            // 2. Production cost and gross profit
            // green inputs get cheaper as regulation builds their market: the premium falls from year 1 to year 3
            var yr = period <= 4 ? 0 : (period <= 8 ? 1 : 2);
            var prodCostMod = 1.0;
            if (d.productionMode === 'hybrid') prodCostMod = [1.12, 1.06, 1.03][yr];
            if (d.productionMode === 'green') prodCostMod = [1.45, 1.12, 1.06][yr];
            var grossProfit = totalRevenue - totalRevenue * (1 - marginRate) * prodCostMod;

            // 3. Sustainability investment
            var sustainCost = totalRevenue * (pct / 100);

            // 4. Carbon regulation: taxed revenue grows with each market regulatory pressure and the carbon intensity
            var taxRate = this.CARBON_TAX[period] || 0;
            var carbonTax = 0;
            if (taxRate > 0) {
                startMarkets.forEach(function(mId) {
                    var m = self._findMarket(mId);
                    if (m) carbonTax += (marketRevenues[mId] || 0) * m.regPressure * (ds.carbonIntensity / 100) * taxRate;
                });
            }

            // 5. Fixed cost of running each market beyond the two home markets
            var overhead = 0;
            startMarkets.forEach(function(mId) { var m = self._findMarket(mId); if (m && !m.home) overhead += self.MARKET_OVERHEAD; });

            // 7. ESG rating: diminishing returns on investment, drift back without it
            var esgChange = this._esgStep(d, pct, ds.esgRating);
            ds.esgRating = Math.max(0, Math.min(100, ds.esgRating + esgChange));

            // 8. Carbon intensity
            var carbonChange = -0.35 * pct;
            if (d.productionMode === 'green') carbonChange -= 7;
            if (d.productionMode === 'hybrid') carbonChange -= 3;
            if (d.productionMode === 'standard') carbonChange -= 0.3;
            ds.carbonIntensity = Math.max(10, Math.round((ds.carbonIntensity + carbonChange) * 10) / 10);

            // 6. Geopolitical and regulatory events, on markets present when the quarter opens
            var eventCost = 0;
            var eventMsg = '';
            if (period === 4) {
                if (startMarkets.indexOf('mercado_norte') !== -1) {
                    eventCost += (marketRevenues['mercado_norte'] || 0) * 0.18;
                    eventMsg = T('event_tariff_active');
                } else {
                    eventMsg = T('event_tariff_safe');
                }
            }
            if (period === 6) {
                var euActive = false;
                var euPenalty = 0;
                ['europa_occidental', 'europa_central'].forEach(function(eid) {
                    if (startMarkets.indexOf(eid) !== -1) {
                        euActive = true;
                        if (ds.carbonIntensity > 80) euPenalty += (marketRevenues[eid] || 0) * 0.25 + 400;
                    }
                });
                if (euActive && euPenalty > 0) {
                    eventCost += euPenalty;
                    eventMsg = T('event_carbon_penalty');
                } else {
                    eventMsg = T('event_carbon_safe');
                }
            }
            if (period === 8) {
                if (ds.esgRating < 60) {
                    eventCost += 600;
                    ds.esgRating = Math.max(0, ds.esgRating - 8);
                    eventMsg = T('event_activist_penalty');
                } else {
                    ds.esgRating = Math.min(100, ds.esgRating + 3);
                    eventMsg = T('event_activist_safe');
                }
            }
            if (period === 10) {
                if (startMarkets.indexOf('asia_sudeste') !== -1) {
                    eventCost += (marketRevenues['asia_sudeste'] || 0) * 0.5 + 500;
                    ds.marketShares['asia_sudeste'] = Math.max(1, (ds.marketShares['asia_sudeste'] || 0) * 0.5);
                    eventMsg = T('event_geo_active');
                } else {
                    eventMsg = T('event_geo_safe');
                }
            }
            if (period === 12) {
                if (pct < 6) {
                    eventCost += totalRevenue * 0.15;
                    ds.esgRating = Math.max(0, ds.esgRating - 10);
                    eventMsg = T('event_climate_penalty');
                } else {
                    eventMsg = T('event_climate_safe');
                }
            }

            // 9. Market entry: the fee is paid now; the opening share depends on the ESG record the market sees at the end of the quarter
            var entryCost = 0;
            var expandedName = '';
            if (d.expandMarket && d.expandMarket !== 'none') {
                var newMarket = this._findMarket(d.expandMarket);
                if (newMarket && ds.activeMarkets.indexOf(d.expandMarket) === -1) {
                    entryCost = newMarket.entryFee;
                    ds.activeMarkets.push(d.expandMarket);
                    var entryFit = this._esgFit(newMarket, ds.esgRating, period);
                    ds.marketShares[d.expandMarket] = 3 + 9 * entryFit;
                    ds.entryQuarter[d.expandMarket] = period;
                    ds.entryFit[d.expandMarket] = Math.round(entryFit * 1000) / 1000;
                    expandedName = newMarket.name;
                }
            }

            // 10. Profit and cash
            var profit = grossProfit - sustainCost - carbonTax - overhead - entryCost - eventCost;
            ds.cash = Math.round(ds.cash + profit);
            ds.lastEvent = eventMsg;

            // 11. Histories
            ds.profitHistory.push(Math.round(profit));
            ds.esgHistory.push(Math.round(ds.esgRating * 10) / 10);
            ds.revenueHistory.push(Math.round(totalRevenue));
            ds.carbonHistory.push(ds.carbonIntensity);

            // platform score: the same dual-scorecard composite getPerformanceSummary derives, from the domainState accumulators, every round
            var runScore = this._scorecard(ds.profitHistory, ds.revenueHistory, ds.esgRating, ds.carbonIntensity, ds.cash);
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: Math.max(0, Math.min(100, Math.round(runScore.composite))) });

            // 12. Update dynamic UI after framework cycle
            setTimeout(function() {
                var st = window.mySimulation.state;
                self._updateMarketOptions(st);
                self._updateEventPanel(st);
                self._applyEndState(st);
            }, 500);

            return {
                period: period,
                revenue: Math.round(totalRevenue),
                profit: Math.round(profit),
                sustainCost: Math.round(sustainCost),
                carbonTax: Math.round(carbonTax),
                entryCost: entryCost,
                eventCost: Math.round(eventCost),
                esgRating: Math.round(ds.esgRating * 10) / 10,
                carbonIntensity: ds.carbonIntensity,
                activeMarkets: ds.activeMarkets.length,
                expandedMarket: expandedName,
                eventMessage: eventMsg,
                cash: ds.cash
            };
        }

        _esgStep(d, pct, rating) {
            var esgChange = 2.6 * Math.sqrt(pct);
            if (d.productionMode === 'green') esgChange += 2.5;
            if (d.productionMode === 'hybrid') esgChange += 1.2;
            if (d.productionMode === 'standard') esgChange -= 0.5;
            if (d.pricingStrategy === 'premium') esgChange += 0.3;
            if (d.pricingStrategy === 'mass') esgChange -= 0.5;
            esgChange -= 0.14 * (rating - 30);
            return esgChange;
        }

        _esgFit(m, esg, period) {
            // buyers reward an ESG record as the regulation that prices it arrives: little in year 1, fully from year 3
            var ramp = period <= 4 ? 0.3 : (period <= 8 ? 0.7 : 1.0);
            var r = (esg - 40) / 35;
            if (r < 0) r = 0;
            if (r > 1) r = 1;
            return m.esgPressure * r * ramp;
        }

