        getPerformanceSummary(history) {
            if (!history.length) return {};
            var T = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};
            var self = this;

            var profits = history.map(function(r) { return r.results && r.results.profit ? r.results.profit : 0; });
            var revenues = history.map(function(r) { return r.results && r.results.revenue ? r.results.revenue : 0; });
            var totalProfit = profits.reduce(function(s, p) { return s + p; }, 0);
            var totalRevenue = revenues.reduce(function(s, r) { return s + r; }, 0);
            var avgProfit = totalProfit / profits.length;

            var lastResult = history[history.length - 1].results || {};
            var finalEsg = (typeof lastResult.esgRating === 'number') ? lastResult.esgRating : 45;
            var finalCarbon = (typeof lastResult.carbonIntensity === 'number') ? lastResult.carbonIntensity : 100;
            var finalMarkets = lastResult.activeMarkets || 2;
            var finalCash = lastResult.cash;
            if (typeof finalCash !== 'number') finalCash = this.START_CASH;

            var sc = this._scorecard(profits, revenues, finalEsg, finalCarbon, finalCash);
            var composite = sc.composite;

            var performanceKey = 'developing';
            if (composite >= 75) performanceKey = 'excellent';
            else if (composite >= 60) performanceKey = 'good';
            else if (composite >= 45) performanceKey = 'satisfactory';
            var performanceLabel = T('perf_' + performanceKey);

            // what this run did, read from its own history
            var decs = history.map(function(r) { return r.decisions || {}; });
            var pcts = decs.map(function(x) { return Number(x.sustainabilityPct) || 0; });
            var avgPct = pcts.reduce(function(s, p) { return s + p; }, 0) / pcts.length;
            var entries = [];
            history.forEach(function(r) {
                var em = (r.decisions || {}).expandMarket;
                var m = em && em !== 'none' ? self._findMarket(em) : null;
                if (m && r.results && r.results.entryCost > 0) entries.push({ id: m.id, period: (r.results.period || r.period), esg: Math.round(r.results.esgRating || 0), mode: (r.decisions || {}).productionMode, pressure: m.esgPressure });
            });
            var earlyGreen = decs.slice(0, 2).some(function(x) { return x.productionMode === 'green'; });
            var entryAhead = entries.filter(function(e) { return e.pressure >= 0.7 && e.mode === 'standard' && e.esg < 60; });
            var lastEntry = entries.length ? entries[entries.length - 1].period : 0;
            var firstEntry = entries.length ? entries[0].period : 0;
            var midPeak = Math.max.apply(null, pcts.slice(6, 10).concat([0]));
            var harvested = pcts.length >= 12 && midPeak >= 5 && Math.min(pcts[10], pcts[11]) <= midPeak - 3;
            var sudeste = entries.some(function(e) { return e.id === 'asia_sudeste' && e.period < 10; });
            // quarters priced premium while the ESG record buyers saw was not yet credible (rating below 55)
            var premiumEarly = history.filter(function(r) { return (r.decisions || {}).pricingStrategy === 'premium' && r.results && typeof r.results.esgRating === 'number' && r.results.esgRating < 55; });

            // turning point: the quarter with the largest fall in operating profit (entry fees are investment, not a fall)
            var ops = history.map(function(r) { var x = r.results || {}; return (x.profit || 0) + (x.entryCost || 0); });
            var tp = 0, worst = 0;
            for (var i = 1; i < ops.length; i++) {
                var fall = ops[i - 1] - ops[i];
                if (fall > worst) { worst = fall; tp = i; }
            }

            var insights = [];
            if (sc.viability === 'insolvent') insights.push(T('ins_insolvent'));
            else if (sc.viability === 'loss_making') insights.push(T('ins_loss_making'));
            if (entryAhead.length) insights.push(T('mis_entry_ahead', { market: self._findMarket(entryAhead[0].id).name, q: entryAhead[0].period, esg: entryAhead[0].esg }));
            if (entries.length >= 4) insights.push(T('mis_overreach', { n: entries.length, q: lastEntry }));
            if (earlyGreen && sc.finScore < this.FIN_GATE) insights.push(T('mis_early_green'));
            if (avgPct < 4 && sc.esgComposite < this.ESG_GATE) insights.push(T('mis_underinvest', { pct: Math.round(avgPct * 10) / 10 }));
            if (harvested) insights.push(T('mis_harvest', { a: midPeak, b: pcts[11] }));
            if (sudeste) insights.push(T('mis_sudeste'));
            if (premiumEarly.length >= 2) insights.push(T('mis_premium_early', { n: premiumEarly.length, esg: Math.round(premiumEarly[0].results.esgRating) }));
            if (!entries.length) insights.push(T('mis_no_growth'));
            else if (firstEntry > 8) insights.push(T('mis_late_entry', { q: firstEntry }));
            if (!insights.length && sc.finGate && sc.esgGate) insights.push(T('ins_sequenced'));

            return {
                totalProfit: totalProfit,
                totalRevenue: totalRevenue,
                avgProfit: Math.round(avgProfit),
                finalEsgRating: finalEsg,
                finalCarbonIntensity: finalCarbon,
                marketsActive: finalMarkets,
                finalCash: finalCash,
                finScore: Math.round(sc.finScore),
                revenueGrowth: Math.round(sc.growth * 100),
                esgScore: Math.round(sc.esgComposite),
                carbonScore: Math.round(100 - finalCarbon),
                rawScore: sc.raw,
                viability: sc.viability,
                turningPoint: tp ? tp + 1 : 0,
                turningFall: Math.round(worst),
                compositeScore: composite,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: performanceKey,
                performanceKey: performanceKey,
                performanceLabel: performanceLabel,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};
            var s = summary || {};
            var money = function(v) { var n = Math.round(v || 0); return (n < 0 ? '-$' : '$') + Math.abs(n).toLocaleString() + 'M'; };
            var lines = [];
            lines.push(T('done_headline', { score: (s.overallScore != null ? s.overallScore : 0), band: s.performanceLabel || '' }));
            var finOk = (s.finScore || 0) >= this.FIN_GATE;
            var esgOk = (s.esgScore || 0) >= this.ESG_GATE;
            var gateKey = finOk && esgOk ? 'gate_both' : (finOk ? 'gate_esg_fail' : (esgOk ? 'gate_fin_fail' : 'gate_none'));
            lines.push(T('done_scorecard', { fin: s.finScore || 0, esg: s.esgScore || 0 }) + ' ' + T(gateKey));
            lines.push(T('done_financial', { profit: money(s.totalProfit), revenue: money(s.totalRevenue), cash: money(s.finalCash), growth: s.revenueGrowth || 0 }));
            lines.push(T('done_esg', { esg: Math.round(s.finalEsgRating || 0), grade: this._getEsgGrade(s.finalEsgRating || 0), carbon: Math.round(s.finalCarbonIntensity || 0) }));
            lines.push(T('done_reach', { n: s.marketsActive || 0 }));
            if (s.turningPoint) lines.push(T('done_turning', { q: s.turningPoint, fall: money(s.turningFall) }));
            if (s.viability === 'insolvent') lines.push(T('done_insolvent'));
            else if (s.viability === 'loss_making') lines.push(T('done_loss_making'));
            if (s.insights && s.insights.length) lines.push(s.insights.join(' '));
            lines.push(T('done_questions'));
            // FIX(demo 2026-10-22): two line breaks without the backslash escape, which the 131 import turns into a
            // real line break inside the quotes (SyntaxError on the platform)
            return lines.join(String.fromCharCode(10, 10));
        }

        _scorecard(profits, revenues, esgRating, carbonIntensity, cash) {
            var totalProfit = 0;
            for (var i = 0; i < profits.length; i++) totalProfit += profits[i] || 0;
            var firstRev = this.BASE_REVENUE;
            var lastRev = revenues.length ? (revenues[revenues.length - 1] || 0) : 0;
            var growth = lastRev / firstRev - 1;
            // growth is judged on the run rate the Board set, so it only counts once the run is long enough to show it
            var horizon = Math.min(1, revenues.length / 12);
            var profitScore = Math.max(0, Math.min(100, 100 * totalProfit / (this.PROFIT_TARGET * horizon || 1)));
            var growthScore = Math.max(0, Math.min(100, 100 * growth / (this.GROWTH_TARGET * horizon || 1)));
            // growth only counts in full when the run also funds it: revenue bought at a loss is not what the Board asked for
            var funded = profitScore >= 50 ? 1 : profitScore / 50;
            var finScore = 0.6 * profitScore + 0.4 * growthScore * funded;
            var esgComposite = 0.6 * esgRating + 0.4 * Math.max(0, 100 - carbonIntensity);
            // a balanced scorecard: the weaker side counts more, so a surplus on one side cannot buy a deficit on the other
            var lo = Math.min(finScore, esgComposite);
            var raw = Math.round(0.6 * lo + 0.4 * (finScore + esgComposite) / 2);
            var finGate = finScore >= this.FIN_GATE;
            var esgGate = esgComposite >= this.ESG_GATE;
            var composite = raw;
            var viability = 'viable';
            if (!(finGate && esgGate)) composite = Math.min(composite, this.CAP_GATE);
            if (cash <= 0) {
                viability = 'insolvent';
                composite = Math.min(composite, this.CAP_INSOLVENT);
            } else if (totalProfit < 0) {
                viability = 'loss_making';
                composite = Math.min(composite, this.CAP_LOSS);
            }
            return { raw: raw, composite: composite, viability: viability, finScore: finScore, profitScore: profitScore,
                growthScore: growthScore, growth: growth, esgComposite: esgComposite, finGate: finGate, esgGate: esgGate };
        }

        _syncControlsFromDecisions(state) {
            var dec = (state && state.decisions) ? state.decisions : null;
            if (!dec) return;
            var set = function(id, val) {
                var el = document.getElementById(id);
                if (el && val !== undefined && val !== null) el.value = String(val);
            };
            set('sustainInput', dec.sustainabilityPct);
            set('pricingSelect', dec.pricingStrategy);
            set('productionSelect', dec.productionMode);
            var exp = document.getElementById('expandSelect');
            if (exp && dec.expandMarket) {
                var ok = false;
                if (exp.options) {
                    for (var i = 0; i < exp.options.length; i++) {
                        if (exp.options[i].value === dec.expandMarket) { ok = true; break; }
                    }
                }
                exp.value = ok ? dec.expandMarket : 'none';
            }
        }

        _applyEndState(state) {
            if (!state) return;
            var maxP = state.maxPeriods || 12;
            var over = (state.currentPeriod > maxP) || ((state.history || []).length >= maxP);
            var controls = document.getElementById('decisionControls');
            var banner = document.getElementById('completionBanner');
            if (controls) controls.style.display = over ? 'none' : '';
            if (banner) banner.style.display = over ? 'block' : 'none';
        }

        getHint(state, results) {
            if (results.eventMessage) return results.eventMessage;
            if (results.expandedMarket) return window.mySimulation.t('hint_entered', { market: results.expandedMarket });
            if (results.profit < 0) return window.mySimulation.t('hint_loss');
            if (state.domainState.esgRating < 40) return window.mySimulation.t('hint_low_esg');
            if (results.carbonTax > 150) return window.mySimulation.t('hint_carbon_tax', { tax: '$' + Math.round(results.carbonTax) + 'M' });
            if (state.domainState.carbonIntensity > 80 && state.currentPeriod > 4) return window.mySimulation.t('hint_high_carbon');
            if (results.profit > 1200) return window.mySimulation.t('hint_great');
            return null;
        }

